public async Task<CheckoutResult> Checkout(CheckoutRequest req) {
    var orderId = Guid.NewGuid();

    // Step 1: Reserve inventory
    var reserve = await _inventory.ReserveAsync(req.Items, orderId);
    if (!reserve.Success) return CheckoutResult.Fail("Out of stock");

    // Step 2: Authorize payment
    var payment = await _payment.AuthorizeAsync(req.PaymentToken, req.Total);
    if (!payment.Success) {
        await _inventory.ReleaseAsync(req.Items, orderId);
        return CheckoutResult.Fail("Payment declined");
    }

    // Step 3: Create order
    await _orderService.CreateAsync(orderId, req);
    return CheckoutResult.Success(orderId);
}
